DELETE FROM attendance_exception_data
WHERE id IN

    #{item}

mapper.update:
UPDATE attendance_exception
SET is_verify = #{verifyCode}
WHERE id = #{id}

mapper.select:
SELECT ae.exception_id id, ae.department, ae.position, ae.`name`, DATE_FORMAT(ae.attendance_month, '%Y年%c月') attendanceMonth, ae.is_verify isVerify, aed.id exceptionDataId, aed.attendance_date attendanceDate, aed.type, DATE_FORMAT(aed.actual_start_work_time, '%H:%i') actualStartWorkTime, DATE_FORMAT(aed.actual_end_work_time, '%H:%i') actualEndWorkTime, (case when d.id is null then 1 else 0 end) as isWorkingDay FROM attendance_exception ae LEFT JOIN attendance_exception_data aed ON aed.exception_id = ae.exception_id left join attendance_non_work_day d on aed.attendance_date BETWEEN d.start_date and d.end_date WHERE ae.id IN ( SELECT temp.id FROM ( SELECT ae.exception_id id FROM attendance_exception ae LEFT JOIN attendance_exception_data aed ON aed.exception_id = ae.exception_id
aed.attendance_date IS NOT NULL
AND ae.attendance_month IN
#{item}
AND ae.position LIKE concat('%',#{position},'%')
AND ae.department LIKE concat('%',#{department},'%')
AND ae.`name` LIKE concat('%',#{name},'%')
AND ae.is_verify = #{isVerify}
GROUP BY ae.exception_id ORDER BY ae.attendance_month DESC, ae.exception_id
limit #{page}, #{row}
) AS temp )

mapper.insert:
INSERT INTO attendance_exception(exception_id ,department, `name`, attendance_month, is_verify) VALUES
(#{item.exceptionId},#{item.department}, #{item.name}, #{item.attendanceMonth}, #{item.isVerify})
ON DUPLICATE KEY UPDATE is_verify = '0';

mapper.select:
SELECT id exceptionId
FROM attendance_exception
WHERE `name` = #{name}
  AND department = #{department}
  AND attendance_month = #{attendanceMonth}
